def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 4
    bg = 9

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def spans(n, cuts):
        result = []
        start = 0
        for x in cuts:
            if start < x:
                result.append((start, x))
            start = x + 1
        if start < n:
            result.append((start, n))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    source = None
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            pattern = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != bg
            ]
            if pattern:
                source = pattern
                break
        if source:
            break

    out = [row[:] for row in grid]
    if source:
        for r0, r1 in row_spans:
            for c0, c1 in col_spans:
                for dr, dc, value in source:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = value
    return out
